insert into public.challenges (id, path_id, skill_id, title, prompt, hint, difficulty, kind, min_seconds) values
    ('python/your-first-program-hello-world', 'python', 'python/getting-started', 'Your first program: Hello World', 'Write a program that prints exactly `Hello, World!`', '`print()` shows whatever you put between its parentheses.', 2, 'coding', 20),
    ('python/strings-and-indexing-slicing', 'python', 'python/primitive-types-and-variables', 'Strings and indexing/slicing', 'Finish `middle(word)` so it returns the word without its first and last letters. `middle("python")` should return `"ytho"`.', 'A slice `word[start:end]` gives the characters from `start` up to, but not including, `end`.', 2, 'coding', 20),
    ('python/formatted-strings-f-strings', 'python', 'python/primitive-types-and-variables', 'Formatted strings (f-strings)', 'Finish `introduce(name, age)` so it returns a sentence like `"Hi, I''m Ada and I''m 36 years old."` Use an f-string.', 'An f-string starts with an `f` right before the opening quote: `f"..."`.', 2, 'coding', 20),
    ('python/essential-string-methods', 'python', 'python/primitive-types-and-variables', 'Essential string methods', 'Finish `clean_username(text)`: remove spaces at both ends, make it lowercase, and replace the spaces between words with underscores. `"  Ada Lovelace "` becomes `"ada_lovelace"`.', 'Strings have methods for each step: one removes whitespace at the ends, one lowercases, one replaces text.', 2, 'coding', 20),
    ('python/arithmetic-operators-and-augmented-assignment', 'python', 'python/primitive-types-and-variables', 'Arithmetic operators and augmented assignment', 'Finish `minutes_and_seconds(total)` so it turns a number of seconds into minutes and the seconds left over. `minutes_and_seconds(125)` returns `(2, 5)`. Use `//` and `%`.', '`/` always gives a float: `125 / 60` is `2.0833…`. You want the whole minutes only.', 2, 'coding', 20),
    ('python/type-conversion-and-type', 'python', 'python/primitive-types-and-variables', 'Type conversion and type()', 'This program should ask for two whole numbers and print their sum, but for 3 and 5 it prints `35`. `input()` always gives you text. Convert both answers to numbers so it prints `8`.', 'Adding two pieces of text joins them: `"3" + "5"` is `"35"`.', 2, 'coding', 20),
    ('python/conditional-statements-if-elif-else', 'python', 'python/control-flow', 'Conditional statements (if / elif / else)', 'Finish `grade(score)`: 90 and above is `"A"`, 80–89 `"B"`, 70–79 `"C"`, 60–69 `"D"`, and below 60 `"F"`.', 'Add an `elif` for each grade, checking the highest scores first.', 2, 'coding', 20),
    ('python/logical-operators-and-or-not', 'python', 'python/control-flow', 'Logical operators (and / or / not)', 'Finish `is_leap_year(year)`. A year is a leap year if it divides by 4, except years that divide by 100, unless they also divide by 400. So 2024 and 2000 are leap years; 2023 and 1900 are not.', '`year % 4 == 0` means "divides by 4". The same pattern works for 100 and 400.', 2, 'coding', 20),
    ('python/for-loops-and-range', 'python', 'python/control-flow', 'For loops and range()', 'Finish `sum_up_to(n)` so it adds up every whole number from 1 to `n` with a `for` loop. `sum_up_to(5)` is 1 + 2 + 3 + 4 + 5 = `15`.', 'The loop is almost right. Print `list(range(1, 5))` to see which numbers it gives.', 2, 'coding', 20),
    ('python/while-loops-and-infinite-loops', 'python', 'python/control-flow', 'While loops and infinite loops', 'Finish `count_digits(n)` so it returns how many digits a non-negative whole number has, using a `while` loop. `count_digits(12345)` is `5` and `count_digits(0)` is `1`.', 'Each time you do `n = n // 10`, the number loses one digit.', 2, 'coding', 20),
    ('python/exercise-fizzbuzz-and-a-guessing-game', 'python', 'python/control-flow', 'Exercise: FizzBuzz and a guessing game', 'Print the numbers from 1 to 15, one per line. For multiples of 3 print `Fizz` instead, for multiples of 5 print `Buzz`, and for multiples of both print `FizzBuzz`.', '`n % 3 == 0` is true when `n` is a multiple of 3.', 2, 'coding', 20),
    ('python/default-argument-values', 'python', 'python/functions', 'Default argument values', 'Change `power` so the exponent is optional and defaults to 2. `power(3)` should return `9`, and `power(2, 10)` should still return `1024`.', 'Right now `power(3)` fails because Python wants a value for every parameter.', 2, 'coding', 20),
    ('python/returning-values-and-returning-none', 'python', 'python/functions', 'Returning values (and returning None)', 'Fix `average(numbers)` so it returns `None` for an empty list instead of crashing. `average([2, 4, 6])` is `4`.', 'For an empty list, `len(numbers)` is 0, and dividing by zero raises `ZeroDivisionError`.', 2, 'coding', 20),
    ('python/exercise-reusable-fibonacci-and-validation-helpers', 'python', 'python/functions', 'Exercise: reusable Fibonacci and validation helpers', 'Finish `fibonacci(n)` so it returns a list of the first `n` Fibonacci numbers. The list starts `0, 1`, and each next number is the sum of the two before it: `fibonacci(7)` is `[0, 1, 1, 2, 3, 5, 8]`.', 'Keep two variables for the last two numbers, starting at `a = 0` and `b = 1`.', 2, 'coding', 20),
    ('python/list-comprehensions', 'python', 'python/data-structures', 'List comprehensions', 'Finish `squares_of_evens(numbers)` with a list comprehension: return the square of every even number, in order. `squares_of_evens([1, 2, 3, 4])` is `[4, 16]`.', 'A list comprehension has the shape `[expression for item in items if condition]`.', 2, 'coding', 20),
    ('python/exercise-word-frequency-counter', 'python', 'python/data-structures', 'Exercise: word frequency counter', 'Finish `word_counts(text)` so it returns a dictionary of how many times each word appears, ignoring upper and lower case. `word_counts("the cat the hat")` is `{"the": 2, "cat": 1, "hat": 1}`.', '`text.lower().split()` gives you a list of lowercase words.', 2, 'coding', 20)
insert into public.projects (id, path_id, title, description, requirements, skill_ids, is_capstone, xp, achievement_id) values ('python/capstone', 'python', 'Command-line expense tracker', 'A program you run in the terminal to record what you spend, see it by category, and keep it between runs.', '["Add expenses (amount, category, note)","Delete expenses","List expenses and totals by category","Save data to a file","Read the data back when the program starts","Handle bad input and a missing or broken data file without crashing"]'::jsonb, array['python/getting-started', 'python/primitive-types-and-variables', 'python/control-flow', 'python/functions', 'python/data-structures', 'python/exceptions', 'python/classes-and-object-oriented-programming', 'python/modules-and-packages', 'python/the-standard-library', 'python/pip-virtual-environments-and-packaging', 'python/popular-libraries', 'python/capstone-project']::text[], true, 500, null)
