insert into public.challenges (id, path_id, skill_id, title, prompt, hint, difficulty, kind, min_seconds) values
    ('javascript/your-first-script-and-the-browser-console', 'javascript', 'javascript/getting-started', 'Your first script and the browser console', 'Write a script that logs exactly `Hello, World!` with `console.log()`.', '`console.log()` prints whatever you pass it.', 2, 'coding', 20),
    ('javascript/template-literals', 'javascript', 'javascript/basics-variables-and-types', 'Template literals', 'Finish `greet(name, city)` with a template literal so it returns a string like `"Hello, Ada from London!"`.', 'Template literals use backticks (`` ` ``) instead of quotes.', 2, 'coding', 20),
    ('javascript/ternary-operator', 'javascript', 'javascript/operators', 'Ternary operator', 'Finish `ticketPrice(age)` with the ternary operator: children under 12 pay `5`, everyone else pays `10`.', 'The ternary operator picks one of two values: `condition ? a : b`.', 2, 'coding', 20),
    ('javascript/nullish-coalescing', 'javascript', 'javascript/operators', 'Nullish coalescing (??)', 'Fix `displayName(user)` so it uses the nickname if there is one, then the name, then `"Anonymous"`. A nickname of `""` counts as a nickname the user chose, so keep it. Only `null` and `undefined` should fall through.', '`||` skips every "falsy" value, and the empty string `""` is falsy.', 2, 'coding', 20),
    ('javascript/switch-case', 'javascript', 'javascript/control-flow', 'switch...case', 'Finish `dayName(day)` with a `switch`: 0 is `"Sunday"`, 1 `"Monday"`, … 6 `"Saturday"`. Any other number returns `"Invalid day"`.', 'Add one `case` per day, each with its own `return`.', 2, 'coding', 20),
    ('javascript/for-loops', 'javascript', 'javascript/control-flow', 'for loops', 'Finish `sumArray(numbers)` so it adds up all the numbers in the array with a `for` loop. `sumArray([1, 2, 3])` is `6`, and an empty array sums to `0`.', 'A classic for loop: `for (let i = 0; i < numbers.length; i++) { ... }`.', 2, 'coding', 20),
    ('javascript/exercises-fizzbuzz-max-of-numbers-star-pattern', 'javascript', 'javascript/control-flow', 'Exercises: FizzBuzz, max of numbers, star pattern', 'Finish `largest(numbers)` so it returns the biggest number in the array, without `Math.max`. Return `null` for an empty array.', 'Try it with `[-5, -1, -9]`: starting at 0, no number is ever bigger than `biggest`.', 2, 'coding', 20),
    ('javascript/object-literals', 'javascript', 'javascript/objects', 'Object literals', 'Finish `createAddress(street, city, zipCode)` so it returns an object with those three properties, like `{ street: "1 Main St", city: "Springfield", zipCode: "12345" }`.', 'An object literal lists `key: value` pairs between braces.', 2, 'coding', 20)
