insert into public.projects (id, path_id, title, description, requirements, skill_ids, is_capstone, xp, achievement_id) values ('postgresql/capstone', 'postgresql', 'PostgreSQL In Depth capstone', 'Build a small but complete project of your own choosing with what you learned in PostgreSQL In Depth, then submit it for review.', '["Solves a real problem you can describe in a sentence","Uses the core ideas from at least half of the course''s modules","Handles bad input and errors without crashing","Organized into sensible files and functions","Includes a short README explaining how to run it and your design decisions","Includes at least a few tests, or a documented way to check it works"]'::jsonb, array['postgresql/getting-started-with-postgres', 'postgresql/postgres-data-types', 'postgresql/schema-design-and-constraints', 'postgresql/advanced-querying', 'postgresql/jsonb-in-practice', 'postgresql/full-text-search', 'postgresql/functions-and-pl-pgsql', 'postgresql/triggers', 'postgresql/indexes-deep-dive', 'postgresql/transactions-mvcc-and-locking', 'postgresql/roles-and-security', 'postgresql/administration-basics', 'postgresql/performance-tuning-capstone']::text[], true, 500, null)
